"""Добавления только к новым авторским урокам; все прежние абзацы сохраняются."""
import json,pathlib
root=pathlib.Path('/workspace/RUS_CHRON/src/content/lessons')
extras={
'01-004':('Проверка на конкретном примере','Представим, что в нижнем слое поселения лежит лепная посуда, а в верхнем появляется круговая. Прежде чем объявить приход нового народа, нужно исследовать, меняются ли одновременно дома, питание и погребения. Возможно, местные жители освоили более производительную технологию или начали покупать сосуды у соседних мастеров. Если новая посуда изготовлена из местной глины и появляется постепенно, это поддерживает одни объяснения. Если одновременно возникают новые устойчивые комплексы и меняется сеть поселений, основания обсуждать переселение становятся сильнее. Даже тогда вывод остаётся моделью исторического процесса, а не чтением национальности непосредственно с поверхности предмета.'),
'01-005':('Сравнение свидетелей','Если античный автор описывает всех степняков одинаково, а раскопки выявляют разные хозяйственные и погребальные практики, эти сведения не нужно искусственно уравнивать. Автор мог обобщать известный ему регион или пользоваться старым описанием. Археология, в свою очередь, может не сохранить некоторые занятия, особенно не оставлявшие прочных вещей. Сильный вывод учитывает обе стороны. Например, сочетание костей домашних животных, следов поселения и привозной керамики позволяет обсуждать конкретное хозяйство увереннее, чем одна эффектная история о кочевой жизни. Отдельно проверяют время: сведения разных столетий не описывают одно и то же общество без изменений.'),
'01-006':('Как читают монету','Монета сообщает имя правителя, городскую символику или особенности денежного обращения. Но она могла долго ходить после выпуска и попасть далеко от места чеканки. Поэтому отдельная находка не доказывает, что город подчинился изображённому правителю именно в год изготовления монеты. Исследователи сравнивают целые серии, состав кладов, надписи и археологические слои. Такой подход помогает различить торговое присутствие, денежное влияние и политическое управление. Для причерноморских городов это особенно существенно: море переносило деньги и товары между центрами с разным устройством власти, а привычные изображения иногда сохранялись после изменения политической обстановки.'),
'01-007':('Рассказ победителя','Письменные источники чаще рассказывают о походах и правителях, чем о жизни земледельцев между войнами. Поэтому рассказ о переселении легко превращается в непрерывную череду сражений. Исправить впечатление помогают поселения, кладбища и хозяйственные следы. Сохранение обработки земли и местной технологии показывает другую сторону эпохи: люди приспосабливались к новым условиям, восстанавливали связи и передавали навыки детям. Военная катастрофа могла изменить власть быстро, тогда как перестройка повседневного хозяйства занимала поколения. Исследовать нужно оба масштаба времени, не отрицая разрушений и не объявляя каждый регион полностью опустевшим после известного похода.'),
'01-008':('Родство без неизменности','Общий языковой предок не означает, что все носители языка происходили от небольшой неизменной группы семей. Язык мог распространяться при смешанных браках, хозяйственных контактах и включении соседей в новые сообщества. Разные культурные навыки при этом сохранялись и соединялись. Поэтому древняя ДНК способна показать родственные связи и перемещения, но генетическое сходство нельзя без проверки называть славянской речью. Человек усваивает язык в обществе, а биологическое наследование подчиняется другим механизмам. Совпадение нескольких рядов данных усиливает историческую гипотезу, но каждый метод сначала должен быть применён корректно в собственной области.'),
'01-009':('Масштаб освоения','Даже при известном направлении расселения важно различать появление отдельного поселения и освоение всего бассейна реки. Между ними могли лежать десятилетия и большие малонаселённые пространства. Торговый пункт с разнообразными находками не обязательно показывает обычный состав всех деревень вокруг него: такие места притягивали гостей, воинов и ремесленников. Сравнение центра и сельской округи помогает увидеть эту разницу. Поэтому выводы о населении региона строят на нескольких типах памятников, учитывая выбор места раскопок. Новая находка может уточнить картину соседства, не отменяя автоматически всех прежних наблюдений о направлении расселения.')}
for id,(title,p) in extras.items():
 path=root/(id+'.json');d=json.loads(path.read_text())
 if any(s['title']==title for s in d['sections']):continue
 # Добавление абзаца к существующему предметному разделу сохраняет шесть разделов.
 d['sections'][-1]['paragraphs'].append(p)
 path.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 print(id,sum(len(p.split()) for s in d['sections'] for p in s['paragraphs']))
